void cmd_lut_insert( Cmd cmd , Exec_Func func, Exec_Mode mode )
{  	
    reg_q_assign_func( cmd_exec_table , (Reg_Id)cmd , (Reg_Func)func , (Reg_Q_Exec_Mode)mode );		
}

/*--------------------------------------------------------------------------*/

void cmd_lut_insert_table1( const Cmd_Array1 *cmd_array , UInt8 size , Exec_Mode mode )
{
  	reg_q_assing_table1(cmd_exec_table,(Reg_Q_Const_Entry1*)cmd_array,size,mode);        
}

/*--------------------------------------------------------------------------*/

void cmd_lut_insert_table2( const Cmd_Array2 *cmd_array , UInt8 size )
{
  	reg_q_assing_table2(cmd_exec_table,(Reg_Q_Const_Entry2*)cmd_array,size);        
}

